set -e
cd "$(dirname "$0")"
mkdir -p site quick-site
printf '%s\n' 'file a' > site/a.txt
printf '%s\n' 'file b' > site/b.txt
printf '%s\n' 'file c' > site/c.txt
printf '%s\n' 'file d' > site/d.txt
printf '%s\n' 'file e' > site/e.txt
printf '%s\n' 'file f' > site/f.txt
printf '%s\n' 'file a' > quick-site/a.txt
printf '%s\n' 'file b' > quick-site/b.txt
surl -v --log-file surl.log --directory site http://127.0.0.1:8080/ &
sleep 1
curl -s -w "%{http_code} %{num_connects}\n" -o /dev/null -o /dev/null -o /dev/null http://127.0.0.1:8080/a.txt http://127.0.0.1:8080/b.txt http://127.0.0.1:8080/c.txt
kill $(jobs -p)
